mapper.select:

select id, bill_type, bill_id, entry_type, entry_id, action_type, before_json, after_json, operator, change_time, tenant_id
from gz_bill_entry_change_log
where IFNULL(is_deleted,0)=0 AND bill_type = #{billType}
  and bill_id = #{billId}
  and tenant_id = #{scopedTenantId}
AND IFNULL(is_deleted,0)=0
order by change_time desc, id desc
